/**
 * A declared output that still carries a placeholder marker is not done yet —
 * the orchestrator treats it as missing.
 */
import fs from 'fs-extra'

const STUB_MARKERS = [
  'TODO:',
  '> Generated by `dqa upgrade',
  '[TBD]',
  '[describe]',
  'expect.assertions(0)',
  '// placeholder',
  '// TODO: import',
]

export async function isStub(filePath: string): Promise<boolean> {
  try {
    const content = await fs.readFile(filePath, 'utf-8')
    return STUB_MARKERS.some(m => content.includes(m))
  } catch {
    return false
  }
}
